"""
Sunken City - greybox level builder.

Run from inside Unreal Editor (Water/Niagara/Python plugins enabled, project
already compiled) via the console command:

    py build_greybox_level.py

It (re)builds /Game/Maps/L_Prototype from Content/Data/level_layout.json:
zone A-F greybox blockout, water/dive volumes, checkpoints, the goal, the
drainage puzzle, 8 discovery items, and a first-pass lighting setup
(directional light, sky light, sky atmosphere, height fog, post process).

Re-running this script is safe: every actor it creates is tagged
"SunkenCity_AutoGenerated" and destroyed before the level is rebuilt, so it
will not duplicate actors you haven't hand-placed yourself. Hand-placed
actors (without the tag) are left untouched.

This script was written to the Unreal 5.4 Python API from documentation and
has not been executed inside the Editor (this environment has no Unreal
install). If a call name has moved in your engine version, the error message
will name the missing attribute - see Docs/SETUP_GUIDE.md for troubleshooting.
"""

import json
import os
import unreal

AUTO_TAG = "SunkenCity_AutoGenerated"
MAP_PATH = "/Game/Maps/L_Prototype"

actor_subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
level_subsystem = unreal.get_editor_subsystem(unreal.LevelEditorSubsystem)
asset_tools = unreal.AssetToolsHelpers.get_asset_tools()

CUBE_MESH = unreal.EditorAssetLibrary.load_asset("/Engine/BasicShapes/Cube.Cube")
WATER_VOLUMES_NEEDING_BRUSH = []


def load_layout():
    layout_path = os.path.join(unreal.Paths.project_content_dir(), "Data", "level_layout.json")
    with open(layout_path, "r", encoding="utf-8") as f:
        return json.load(f)


def ensure_level():
    if unreal.EditorAssetLibrary.does_asset_exist(MAP_PATH):
        level_subsystem.load_level(MAP_PATH)
    else:
        level_subsystem.new_level(MAP_PATH)


def clear_previous_generation():
    for actor in actor_subsystem.get_all_level_actors():
        if AUTO_TAG in [str(t) for t in actor.tags]:
            actor_subsystem.destroy_actor(actor)


def tag_actor(actor, label):
    actor.set_actor_label(label, mark_dirty=True)
    actor.tags = [unreal.Name(AUTO_TAG)]
    actor.set_folder_path("SunkenCity_Generated")
    return actor


def spawn(cls, location, label, rotation=None):
    rot = rotation if rotation else unreal.Rotator(0, 0, 0)
    actor = actor_subsystem.spawn_actor_from_class(cls, unreal.Vector(*location), rot)
    tag_actor(actor, label)
    return actor


def spawn_block(center, size, label, mesh=None):
    """Spawn a StaticMeshActor cube covering `size` (full extents, cm) centered at `center`."""
    actor = spawn(unreal.StaticMeshActor, center, label)
    mesh_comp = actor.get_editor_property("static_mesh_component")
    mesh_comp.set_editor_property("static_mesh", mesh or CUBE_MESH)
    # /Engine/BasicShapes/Cube is 100x100x100uu, so scale = size / 100.
    scale = unreal.Vector(size[0] / 100.0, size[1] / 100.0, size[2] / 100.0)
    actor.set_actor_scale3d(scale)
    mesh_comp.set_mobility(unreal.ComponentMobility.STATIC)
    return actor


def build_zone_A(zone):
    spawn_block(zone["center"], zone["size"], "Zone_A_StartPlateau")


def build_zone_B(zone):
    spawn_block(zone["center"], zone["size"], "Zone_B_RoadBed")
    build_water_volume(zone["water_footprint_center"], zone["water_footprint_size"], "Zone_B_WaterVolume")
    build_dive_zone(zone["center"], [zone["size"][0] - 100, zone["size"][1] - 100, zone["size"][2] - 200], "Zone_B_DiveZone")


def build_water_volume(location, size, label):
    # NOTE: AVolume/APhysicsVolume actors spawned from Python get an empty BSP
    # brush (only the "Place Actors" drag-drop path auto-builds a cube brush).
    # This actor is placed at the right location/scale as a reference, but you
    # must give it real geometry once in the editor: select it, open
    # Details > Brush Settings, set X/Y/Z, click Build. See Docs/SETUP_GUIDE.md.
    cls = _load_native_class("WaterVolumePrototype")
    actor = spawn(cls, location, label)
    actor.set_actor_scale3d(unreal.Vector(size[0] / 100.0, size[1] / 100.0, size[2] / 100.0))
    WATER_VOLUMES_NEEDING_BRUSH.append(label)
    return actor


def build_dive_zone(location, size, label):
    cls = _load_native_class("DiveZoneVolume")
    actor = spawn(cls, location, label)
    box = actor.get_editor_property("Volume")
    box.set_editor_property("box_extent", unreal.Vector(size[0] / 2.0, size[1] / 2.0, size[2] / 2.0))
    return actor


def _load_native_class(class_name):
    cls = unreal.find_class(class_name)
    if cls is None:
        raise RuntimeError(
            f"Could not find native class '{class_name}'. Make sure the SunkenCity C++ module "
            f"has compiled successfully (Live Coding / rebuild) before running this script."
        )
    return cls


def build_zone_C(zone):
    cx, cy = zone["center"][0], zone["center"][1]
    fx, fy = zone["footprint"]
    height = zone["wall_height"]
    thickness = zone["wall_thickness"]
    base_z = zone["center"][2]

    # Floor (flooded ground level).
    spawn_block([cx, cy, base_z - height / 2.0], [fx, fy, 40], "Zone_C_Floor")

    # Four walls.
    spawn_block([cx, cy - fy / 2.0, base_z], [fx, thickness, height], "Zone_C_Wall_South")
    spawn_block([cx, cy + fy / 2.0, base_z], [fx, thickness, height], "Zone_C_Wall_North")
    spawn_block([cx - fx / 2.0, cy, base_z], [thickness, fy, height], "Zone_C_Wall_West")
    spawn_block([cx + fx / 2.0, cy, base_z], [thickness, fy, height], "Zone_C_Wall_East")

    # Partial roof with a gap in the middle for light shafts.
    gap_x, gap_y = zone["roof_gap_size"]
    roof_z = base_z + height / 2.0
    # Two roof strips flanking the gap (leaves an opening = roof_gap_size).
    strip_width_y = (fy - gap_y) / 2.0
    spawn_block([cx, cy - (gap_y / 2.0 + strip_width_y / 2.0), roof_z], [fx, strip_width_y, 60], "Zone_C_Roof_South")
    spawn_block([cx, cy + (gap_y / 2.0 + strip_width_y / 2.0), roof_z], [fx, strip_width_y, 60], "Zone_C_Roof_North")

    # Flooded interior water volume + dive zone.
    build_water_volume([cx, cy, zone["floor_water_z"] - 50], [fx - thickness * 2, fy - thickness * 2, 200], "Zone_C_WaterVolume")
    build_dive_zone([cx, cy, zone["floor_water_z"] - 150], [fx - thickness * 2, fy - thickness * 2, 300], "Zone_C_DiveZone")


def build_zone_D(zone):
    spawn_block(zone["center"], zone["size"], "Zone_D_TunnelShell")
    build_water_volume(zone["center"], [zone["size"][0] - 100, zone["size"][1] - 100, zone["size"][2] - 100], "Zone_D_WaterVolume")
    dive = build_dive_zone(zone["center"], [zone["size"][0] - 100, zone["size"][1] - 100, zone["size"][2] - 100], "Zone_D_DiveZone")
    return dive


def build_zone_E(zone, puzzle):
    spawn_block(zone["center"], zone["size"], "Zone_E_RoomShell")
    water_center = [zone["center"][0], zone["center"][1], zone["water_start_z"]]
    water = build_water_volume(water_center, [zone["size"][0] - 100, zone["size"][1] - 100, 100], puzzle["water_body_id"])
    build_dive_zone(water_center, [zone["size"][0] - 100, zone["size"][1] - 100, 300], "Zone_E_DiveZone")
    return water


def build_zone_F(zone):
    tower_center = zone["center"]
    tower_size = zone["size"]
    spawn_block(tower_center, tower_size, "Zone_F_TowerShaft")
    platform_center = [tower_center[0], tower_center[1], zone["platform_top_z"] + 25]
    spawn_block(platform_center, [tower_size[0] * 2.5, tower_size[1] * 2.5, 50], "Zone_F_ViewPlatform")


def build_checkpoints(checkpoints):
    cls = _load_native_class("Checkpoint")
    for cp in checkpoints:
        spawn(cls, cp["location"], cp["id"])


def build_goal(goal):
    cls = _load_native_class("GoalVolume")
    spawn(cls, goal["location"], "Goal_TowerTop")


def build_puzzle(puzzle, gate_actor, water_actor):
    cls = _load_native_class("EnvironmentPuzzle_FloodGate")
    lever = spawn(cls, puzzle["lever_location"], puzzle["id"])
    lever.set_editor_property("GatesToOpen", [gate_actor] if gate_actor else [])
    lever.set_editor_property("WaterBodiesToLower", [water_actor] if water_actor else [])
    lever.set_editor_property("GateOpenHeight", puzzle["gate_open_height"])
    lever.set_editor_property("WaterLowerAmount", puzzle["water_lower_amount"])
    lever.set_editor_property("ActivationDuration", puzzle["activation_duration"])


def build_gate(puzzle):
    gate = spawn_block(puzzle["gate_location"], puzzle["gate_size"], puzzle["gate_actor_id"])
    return gate


def ensure_discovery_data_asset(entry):
    package_path = "/Game/Data/Discoveries"
    asset_name = f"DA_{entry['id']}"
    full_path = f"{package_path}/{asset_name}"

    if unreal.EditorAssetLibrary.does_asset_exist(full_path):
        return unreal.EditorAssetLibrary.load_asset(full_path)

    factory = unreal.DataAssetFactory()
    factory.set_editor_property("data_asset_class", _load_native_class("DiscoveryItemData"))
    asset = asset_tools.create_asset(asset_name, package_path, None, factory)
    asset.set_editor_property("DiscoveryId", unreal.Name(entry["id"]))
    asset.set_editor_property("DisplayName", unreal.Text(entry["display_name"]))
    asset.set_editor_property("ShortDescription", unreal.Text(entry["description"]))
    unreal.EditorAssetLibrary.save_asset(full_path)
    return asset


def build_discoveries(discoveries):
    cls = _load_native_class("DiscoveryItem")
    for entry in discoveries:
        data_asset = ensure_discovery_data_asset(entry)
        actor = spawn(cls, entry["location"], f"Discovery_{entry['id']}")
        mesh_comp = actor.get_editor_property("MeshComponent")
        mesh_comp.set_editor_property("static_mesh", CUBE_MESH)
        actor.set_actor_scale3d(unreal.Vector(0.3, 0.3, 0.3))
        actor.set_editor_property("ItemData", data_asset)


def build_lighting():
    sun = spawn(unreal.DirectionalLight, [0, 0, 3000], "Lighting_Sun", unreal.Rotator(-50, -30, 0))
    light_comp = sun.get_editor_property("light_component")
    light_comp.set_editor_property("intensity", 6.5)
    light_comp.set_editor_property("light_color", unreal.LinearColor(1.0, 0.92, 0.78, 1.0))
    light_comp.set_editor_property("atmosphere_sun_light", True)
    light_comp.set_editor_property("cast_shadows", True)

    spawn(unreal.SkyLight, [0, 0, 3000], "Lighting_SkyLight")

    spawn(unreal.SkyAtmosphere, [0, 0, 0], "Lighting_SkyAtmosphere")

    fog = spawn(unreal.ExponentialHeightFog, [0, 0, 0], "Lighting_HeightFog")
    fog_comp = fog.get_editor_property("component")
    fog_comp.set_editor_property("fog_density", 0.02)
    fog_comp.set_editor_property("fog_inscattering_color", unreal.LinearColor(0.55, 0.65, 0.6, 1.0))
    fog_comp.set_editor_property("volumetric_fog", True)
    fog_comp.set_editor_property("volumetric_fog_scattering_distribution", 0.7)

    ppv = spawn(unreal.PostProcessVolume, [0, 0, 0], "Lighting_PostProcess")
    ppv.set_editor_property("unbound", True)
    settings = ppv.get_editor_property("settings")
    settings.bloom_intensity = 1.2
    settings.auto_exposure_bias = 0.5
    ppv.set_editor_property("settings", settings)


def build_player_start(location):
    spawn(unreal.PlayerStart, location, "SunkenCity_PlayerStart")


def main():
    layout = load_layout()
    ensure_level()
    clear_previous_generation()

    zones = {z["id"]: z for z in layout["zones"]}

    build_zone_A(zones["A"])
    build_zone_B(zones["B"])
    build_zone_C(zones["C"])
    d_dive = build_zone_D(zones["D"])
    e_water = build_zone_E(zones["E"], layout["puzzle"])
    build_zone_F(zones["F"])

    gate_actor = build_gate(layout["puzzle"])
    build_puzzle(layout["puzzle"], gate_actor, e_water)

    build_checkpoints(layout["checkpoints"])
    build_goal(layout["goal"])
    build_discoveries(layout["discoveries"])
    build_player_start(layout["player_start"]["location"])
    build_lighting()

    level_subsystem.save_current_level()
    unreal.log(f"Sunken City: greybox build complete. Actors tagged '{AUTO_TAG}' for safe re-runs.")
    unreal.log_warning(
        "Sunken City: the following Volume actors were placed but likely have an EMPTY brush "
        "(Python cannot auto-build BSP brushes). For each one, select it, open Details > Brush "
        "Settings, set X/Y/Z to its intended size, and click Build - see Docs/SETUP_GUIDE.md Phase 2: "
        + ", ".join(WATER_VOLUMES_NEEDING_BRUSH)
    )


main()
